insert into public.comments(id,task_id,author_id,content,created_at) values
('00000004-0000-0000-0000-000000000001','00000003-0000-0000-0000-000000000006','00000001-0000-0000-0000-000000000003','Stripe webhooks are set up. Working through the subscription lifecycle edge cases now.',now()-interval'3d'),
('00000004-0000-0000-0000-000000000002','00000003-0000-0000-0000-000000000006','00000001-0000-0000-0000-000000000002','Make sure we handle failed payment retries. The old system just dropped them silently.',now()-interval'2d'),
('00000004-0000-0000-0000-000000000003','00000003-0000-0000-0000-000000000006','00000001-0000-0000-0000-000000000003','Good catch @Marcus. Adding retry logic and a failed_payments table today.',now()-interval'1d'),
('00000004-0000-0000-0000-000000000004','00000003-0000-0000-0000-000000000007','00000001-0000-0000-0000-000000000001','Bell icon is in, unread count works. Starting the dropdown panel now.',now()-interval'4d'),
('00000004-0000-0000-0000-000000000005','00000003-0000-0000-0000-000000000007','00000001-0000-0000-0000-000000000002','Will we support mark-all-read? Would be nice for the first version.',now()-interval'3d'),
('00000004-0000-0000-0000-000000000006','00000003-0000-0000-0000-000000000012','00000001-0000-0000-0000-000000000002','Found two endpoints missing rate limiting. Filing separate issues for each.',now()-interval'2d'),
('00000004-0000-0000-0000-000000000007','00000003-0000-0000-0000-000000000012','00000001-0000-0000-0000-000000000001','Prioritize the auth endpoints. Those are the most exposed.',now()-interval'1d'),
('00000004-0000-0000-0000-000000000008','00000003-0000-0000-0001-000000000006','00000001-0000-0000-0000-000000000005','First prototype is done. Loom recording in the Figma comments.',now()-interval'2d')
